import csv
import json
from typing import List, Dict, Tuple, Any


def load_orders(path: str) -> List[Dict[str, str]]:
    """Load orders from a CSV file."""
    rows = []
    with open(path) as f:
        for row in csv.DictReader(f):
            rows.append(row)
    return rows


def total_by_customer(rows: List[Dict[str, str]]) -> Dict[str, float]:
    """Calculate total order amount per customer."""
    totals = {}
    for row in rows:
        name = row["customer"]
        amount = float(row["amount"])
        if name not in totals:
            totals[name] = 0.0
        totals[name] += amount
    return totals


def top_customers(totals: Dict[str, float], n: int) -> List[Tuple[str, float]]:
    """Get the top n customers by total order amount."""
    items = sorted(totals.items(), key=lambda kv: kv[1], reverse=True)
    return items[:n]


def filter_by_status(rows: List[Dict[str, str]], status: str) -> List[Dict[str, str]]:
    """Filter orders by their status."""
    out = []
    for row in rows:
        if row["status"] == status:
            out.append(row)
    return out


def average_order_value(rows: List[Dict[str, str]]) -> float:
    """Calculate the average order value."""
    if not rows:
        return 0.0
    total = 0.0
    for row in rows:
        total += float(row["amount"])
    return total / len(rows)


def save_report(path: str, totals: Dict[str, float], top: List[Tuple[str, float]]) -> None:
    """Save a report to a JSON file."""
    report = {"totals": totals, "top": top}
    with open(path, "w") as f:
        json.dump(report, f, indent=2)


def main() -> None:
    """Run the main program."""
    rows = load_orders("orders.csv")
    paid = filter_by_status(rows, "paid")
    totals = total_by_customer(paid)
    top = top_customers(totals, 5)
    print("average order value:", average_order_value(paid))
    save_report("report.json", totals, top)


if __name__ == "__main__":
    main()
```

